Method.Source:
[DataMemberAttribute('useExistingDates'), 
    SysOperationLabelAttribute(literalstr("@GeneralLedger:TransactionReversalStatusUseExistingDate")),
    SysOperationDisplayOrderAttribute('1')
]
public boolean parmUseExistingDates(boolean _useExistingDates = useExistingDates)
{
    useExistingDates = _useExistingDates;
    return useExistingDates;
}

[DataMemberAttribute,
    SysOperationLabel(literalStr("@NDX:NXAReversalDate")),
    SysOperationDisplayOrderAttribute('2')
]
public date parmReversalDate(date _reversalDate = reversalDate)
{
    reversalDate = _reversalDate;
    return reversalDate;
}

    [DataMemberAttribute,
        SysOperationLabel(literalStr("@NDX:NXAReversalReason")),
        SysOperationDisplayOrderAttribute('3')
]
    public Description parmreversalReason(Description _reversalReason = reversalReason)
    {
        reversalReason = _reversalReason;
        return reversalReason;
    }

[DataMemberAttribute, SysOperationControlVisibilityAttribute(false)]
public container parmRecordCon(container _recordCon = recordCon)
{
    recordCon = _recordCon;

    return recordCon;
}
